use crate::SomeSharedData;
use futures_util::stream::once;
use worker::{
    email::{EmailAddress, EmailAttachment, EmailMessage, SendEmail, SendEmailBuilder},
    js_sys::Uint8Array,
    worker_sys, Date, Env, FixedLengthStream, Request, Response, Result,
};

const SENDER: &str = "allowed-sender@example.com";
const RECIPIENT: &str = "allowed-recipient@example.com";
const BAD_SENDER: &str = "evil@example.com";
const BAD_RECIPIENT: &str = "nope@example.com";
const MISMATCHED_FROM: &str = "mismatched@example.com";

struct MimeScenario {
    envelope_from: &'static str,
    envelope_to: &'static str,
    header_from: &'static str,
    include_message_id: bool,
}

impl MimeScenario {
    fn for_name(name: &str) -> Option<Self> {
        Some(match name {
            "mime-ok" => Self {
                envelope_from: SENDER,
                envelope_to: RECIPIENT,
                header_from: SENDER,
                include_message_id: true,
            },
            "mime-missing-message-id" => Self {
                envelope_from: SENDER,
                envelope_to: RECIPIENT,
                header_from: SENDER,
                include_message_id: false,
            },
            "mime-disallowed-sender" => Self {
                envelope_from: BAD_SENDER,
                envelope_to: RECIPIENT,
                header_from: BAD_SENDER,
                include_message_id: true,
            },
            "mime-disallowed-recipient" => Self {
                envelope_from: SENDER,
                envelope_to: BAD_RECIPIENT,
                header_from: SENDER,
                include_message_id: true,
            },
            "mime-from-mismatch" => Self {
                envelope_from: SENDER,
                envelope_to: RECIPIENT,
                header_from: MISMATCHED_FROM,
                include_message_id: true,
            },
            _ => return None,
        })
    }

    fn raw(&self) -> String {
        let mut raw = format!(
            "From: {}\r\n\
             To: {}\r\n\
             Subject: Integration test\r\n\
             Date: Thu, 01 Jan 1970 00:00:00 +0000\r\n",
            self.header_from, self.envelope_to
        );
        if self.include_message_id {
            raw.push_str(&format!(
                "Message-ID: <{}@example.com>\r\n",
                Date::now().as_millis()
            ));
        }
        raw.push_str("\r\nhello from an integration test\r\n");
        raw
    }
}

fn build_structured(name: &str) -> Option<SendEmailBuilder> {
    let subject = "structured integration test";
    let builder = match name {
        "structured-ok" => SendEmailBuilder::builder(SENDER, RECIPIENT, subject)
            .text("hello from the structured path"),
        "structured-with-name" => {
            let address = EmailAddress::new("Integration", SENDER);
            SendEmailBuilder::builder_with_email_address_and_str(&address, RECIPIENT, subject)
                .html("<p>hello from the structured path</p>")
        }
        "structured-disallowed-sender" => {
            SendEmailBuilder::builder(BAD_SENDER, RECIPIENT, subject).text("hello")
        }
        "structured-disallowed-recipient" => {
            SendEmailBuilder::builder(SENDER, BAD_RECIPIENT, subject).text("hello")
        }
        // Exercises `EmailAttachment::new_attachment_with_typed_array<T:
        // js_sys::TypedArray>` — the generic builder ts-gen emits for the
        // `content: string | ArrayBuffer | ArrayBufferView` union. The
        // `Uint8Array` flows through wasm-bindgen's generic extern signature
        // straight into the underlying setter, smoke-testing both ends of
        // the codegen.
        "structured-with-attachment" => {
            let payload = b"hello attachment";
            let bytes = unsafe { Uint8Array::view(payload) };
            let attachment =
                EmailAttachment::new_attachment_with_typed_array("hello.txt", "text/plain", &bytes);
            SendEmailBuilder::builder(SENDER, RECIPIENT, subject)
                .text("structured email with an attachment")
                .attachments(&[attachment])
        }
        _ => return None,
    };
    Some(builder.build())
}

#[worker::send]
pub async fn handle_send_email(req: Request, env: Env, _data: SomeSharedData) -> Result<Response> {
    let url = req.url()?;
    let name = url
        .query_pairs()
        .find_map(|(k, v)| (k == "scenario").then(|| v.into_owned()))
        .unwrap_or_default();

    let sender = env.send_email("EMAIL")?;

    if name == "mime-stream" {
        return respond(dispatch_mime_stream(&sender).await);
    }

    if let Some(scenario) = MimeScenario::for_name(&name) {
        return respond(dispatch_mime(&sender, &scenario).await);
    }

    if let Some(builder) = build_structured(&name) {
        return respond(dispatch_structured(&sender, builder).await);
    }

    Response::error(format!("unknown scenario: {name}"), 400)
}

async fn dispatch_mime(sender: &SendEmail, scenario: &MimeScenario) -> Result<String> {
    let message = EmailMessage::new(
        scenario.envelope_from,
        scenario.envelope_to,
        &scenario.raw(),
    )?;
    let result = sender.send(&message).await?;
    Ok(result.message_id())
}

// Exercises the `EmailMessage::new_with_readable_stream` constructor — the
// `&str` raw path is covered by `dispatch_mime`. Builds a one-chunk
// `FixedLengthStream` and pulls the readable side off the underlying
// `TransformStream` via Deref (`FixedLengthStream` extends
// `web_sys::TransformStream`, so `.readable()` resolves through it).
async fn dispatch_mime_stream(sender: &SendEmail) -> Result<String> {
    let scenario = MimeScenario::for_name("mime-ok").expect("mime-ok scenario must exist");
    let raw = scenario.raw().into_bytes();
    let len = raw.len() as u64;
    let fixed: worker_sys::FixedLengthStream =
        FixedLengthStream::wrap(once(async move { Ok(raw) }), len).into();
    let stream = fixed.readable();
    let message = EmailMessage::new_with_readable_stream(
        scenario.envelope_from,
        scenario.envelope_to,
        &stream,
    )?;
    let result = sender.send(&message).await?;
    Ok(result.message_id())
}

async fn dispatch_structured(sender: &SendEmail, builder: SendEmailBuilder) -> Result<String> {
    let result = sender.send_with_builder(&builder).await?;
    Ok(result.message_id())
}

fn respond(result: Result<String>) -> Result<Response> {
    Response::from_json(&serde_json::json!({
        "ok": result.is_ok(),
        "messageId": result.as_ref().ok(),
        "error": result.err().map(|e| e.to_string()),
    }))
}

import { describe, test, expect } from "vitest";
import { mf, mfUrl } from "./mf";

type SendResult = {
  ok: boolean;
  messageId: string | null;
  error: string | null;
};

async function runScenario(name: string): Promise<SendResult> {
  const resp = await mf.dispatchFetch(`${mfUrl}send-email?scenario=${name}`);
  expect(resp.status).toBe(200);
  return (await resp.json()) as SendResult;
}

function expectSuccess(result: SendResult) {
  expect(result.error).toBeNull();
  expect(result.ok).toBe(true);
  expect(result.messageId).toBeTruthy();
}

describe("send email (raw MIME)", () => {
  test("sends a valid email through the binding", async () => {
    expectSuccess(await runScenario("mime-ok"));
  });

  test("sends a valid email constructed from a ReadableStream", async () => {
    expectSuccess(await runScenario("mime-stream"));
  });

  test.each([
    ["mime-missing-message-id", /message-id/i],
    ["mime-disallowed-sender", /email from .* not allowed/i],
    ["mime-disallowed-recipient", /email to .* not allowed/i],
    ["mime-from-mismatch", /from.*does not match/i],
  ])("rejects scenario %s", async (scenario, errorPattern) => {
    const result = await runScenario(scenario);
    expect(result.ok).toBe(false);
    expect(result.error).toMatch(errorPattern);
  });
});

describe("send email (structured builder)", () => {
  test("sends a plain-text email", async () => {
    expectSuccess(await runScenario("structured-ok"));
  });

  test("sends an HTML email with a display-name sender", async () => {
    expectSuccess(await runScenario("structured-with-name"));
  });

  // Exercises ts-gen's generic dictionary builder for the
  // `string | ArrayBuffer | ArrayBufferView` content union — passes a
  // `Uint8Array` directly into `EmailAttachment::new_attachment_with_typed_array`.
  test("sends an email with a typed-array attachment", async () => {
    expectSuccess(await runScenario("structured-with-attachment"));
  });

  test.each([
    ["structured-disallowed-sender", /email from .* not allowed/i],
    ["structured-disallowed-recipient", /email to .* not allowed/i],
  ])("rejects scenario %s", async (scenario, errorPattern) => {
    const result = await runScenario(scenario);
    expect(result.ok).toBe(false);
    expect(result.error).toMatch(errorPattern);
  });
});

use super::SomeSharedData;
use futures_util::stream::StreamExt;
use rand::RngExt;
use std::{borrow::ToOwned, time::Duration};
use worker::{
    console_log, ok, Cache, Date, Delay, Env, Request, Response, ResponseBuilder, Result,
};

fn key(req: &Request) -> Result<Option<String>> {
    let uri = req.url()?;
    let mut segments = uri.path_segments().unwrap();
    Ok(segments.nth(2).map(ToOwned::to_owned))
}

#[worker::send]
pub async fn handle_cache_example(
    req: Request,
    _env: Env,
    _data: SomeSharedData,
) -> Result<Response> {
    console_log!("url: {}", req.url()?.to_string());
    let cache = Cache::default();
    let key = req.url()?.to_string();
    if let Some(resp) = cache.get(&key, true).await? {
        console_log!("Cache HIT!");
        Ok(resp)
    } else {
        console_log!("Cache MISS!");
        // Cache API respects Cache-Control headers. Setting s-max-age to 10
        // will limit the response to be in cache for 10 seconds max
        let mut resp = ResponseBuilder::new()
            .with_header("cache-control", "s-maxage=10")?
            .from_json(&serde_json::json!({ "timestamp": Date::now().as_millis() }))?;
        cache.put(key, resp.cloned()?).await?;
        Ok(resp)
    }
}

#[worker::send]
pub async fn handle_cache_api_get(
    req: Request,
    _env: Env,
    _data: SomeSharedData,
) -> Result<Response> {
    if let Some(key) = key(&req)? {
        let cache = Cache::default();
        if let Some(resp) = cache.get(format!("https://{key}"), true).await? {
            return Ok(resp);
        }
        return Response::ok("cache miss");
    }
    Response::error("key missing", 400)
}

#[worker::send]
pub async fn handle_cache_api_put(
    req: Request,
    _env: Env,
    _data: SomeSharedData,
) -> Result<Response> {
    if let Some(key) = key(&req)? {
        let cache = Cache::default();
        // Cache API respects Cache-Control headers. Setting s-max-age to 10
        // will limit the response to be in cache for 10 seconds max
        let mut resp = ResponseBuilder::new()
            .with_header("cache-control", "s-maxage=10")?
            .from_json(&serde_json::json!({ "timestamp": Date::now().as_millis() }))?;
        cache.put(format!("https://{key}"), resp.cloned()?).await?;
        return Ok(resp);
    }
    Response::error("key missing", 400)
}

#[worker::send]
pub async fn handle_cache_api_delete(
    req: Request,
    _env: Env,
    _data: SomeSharedData,
) -> Result<Response> {
    if let Some(key) = key(&req)? {
        let cache = Cache::default();

        let res = cache.delete(format!("https://{key}"), true).await?;
        return Response::ok(serde_json::to_string(&res)?);
    }
    Response::error("key missing", 400)
}

#[worker::send]
pub async fn handle_cache_stream(
    req: Request,
    _env: Env,
    _data: SomeSharedData,
) -> Result<Response> {
    console_log!("url: {}", req.url()?.to_string());
    let cache = Cache::default();
    let key = req.url()?.to_string();
    if let Some(resp) = cache.get(&key, true).await? {
        console_log!("Cache HIT!");
        Ok(resp)
    } else {
        console_log!("Cache MISS!");
        let mut rng = rand::rng();
        let count = rng.random_range(0..10);
        let stream = futures_util::stream::repeat("Hello, world!\n")
            .take(count)
            .then(|text| async move {
                Delay::from(Duration::from_millis(50)).await;
                ok::Ok(text.as_bytes().to_vec())
            });

        // Cache API respects Cache-Control headers. Setting s-max-age to 10
        // will limit the response to be in cache for 10 seconds max
        let mut resp = ResponseBuilder::new()
            .with_header("cache-control", "s-maxage=10")?
            .from_stream(stream)?;
        console_log!("resp = {:?}", resp);
        cache.put(key, resp.cloned()?).await?;
        Ok(resp)
    }
}

import { describe, test, expect } from "vitest";
import { mf, mfUrl } from "./mf";

describe("cache", () => {
  test("cache example", async () => {
    const resp = await mf.dispatchFetch(`${mfUrl}cache-example`);
    const { timestamp } = (await resp.json()) as { timestamp: unknown };

    for (let i = 0; i < 5; i++) {
      const resp = await mf.dispatchFetch(`${mfUrl}cache-example`);
      const data = (await resp.json()) as { timestamp: unknown };

      expect(data.timestamp).toBe(timestamp);
    }
  });

  test("cache stream", async () => {
    const resp = await mf.dispatchFetch(`${mfUrl}cache-stream`);
    const body = await resp.text();

    for (let i = 0; i < 5; i++) {
      const resp = await mf.dispatchFetch(`${mfUrl}cache-stream`);
      const cachedBody = await resp.text();

      expect(cachedBody).toBe(body);
    }
  });

  test("cache api", async () => {
    const key = "example.org";
    const getEndpoint = `${mfUrl}cache-api/get/${key}`;
    const putEndpoint = `${mfUrl}cache-api/put/${key}`;
    const deleteEndpoint = `${mfUrl}cache-api/delete/${key}`;

    // First time should result in cache miss
    let resp = await mf.dispatchFetch(getEndpoint);
    expect(await resp.text()).toBe("cache miss");

    // Add key to cache
    resp = await mf.dispatchFetch(putEndpoint, { method: "put" });
    const { timestamp: expectedTimestamp } = (await resp.json()) as {
      timestamp: unknown;
    };

    // Should now be cache hit
    resp = await mf.dispatchFetch(getEndpoint);
    let data = (await resp.json()) as { timestamp: unknown };
    expect(data.timestamp).toBe(expectedTimestamp);

    // Delete key from cache
    resp = await mf.dispatchFetch(deleteEndpoint, { method: "post" });
    expect(await resp.text()).toBe('"Success"');

    // Delete key from cache
    resp = await mf.dispatchFetch(getEndpoint);
    expect(await resp.text()).toBe("cache miss");

    // Another delete should fail
    resp = await mf.dispatchFetch(deleteEndpoint, { method: "post" });
    expect(await resp.text()).toBe('"ResponseNotFound"');
  });
});

use wasm_bindgen::prelude::*;

mod glue {
    use super::*;

    #[wasm_bindgen]
    extern "C" {
        #[wasm_bindgen]
        pub type CacheStorage;

        #[wasm_bindgen(method, catch, getter)]
        pub fn default(this: &CacheStorage) -> Result<web_sys::Cache, JsValue>;
    }
}

pub trait CacheStorageExt {
    fn default(&self) -> web_sys::Cache;
}

impl CacheStorageExt for web_sys::CacheStorage {
    fn default(&self) -> web_sys::Cache {
        self.unchecked_ref::<glue::CacheStorage>()
            .default()
            .unwrap()
    }
}
